203 :     CompilerInput varInput = var.input;
204 :     if (currInput == varInput || currInput == null || varInput == null) {
205 :       // The variable was defined in the same file. This is fine.
206 :       return;
207 :     }
208 : 
209 :     // Check module dependencies.
210 :     JSModule currModule = currInput.getModule();
211 :     JSModule varModule = varInput.getModule();
212 :     JSModuleGraph moduleGraph = compiler.getModuleGraph();
213 :     if (!sanityCheck &&
214 :         varModule != currModule && varModule != null && currModule != null) {
215 :       if (moduleGraph.dependsOn(currModule, varModule)) {
216 :         // The module dependency was properly declared.
217 :       } else {
218 :         if (scope.isGlobal()) {
219 :           if (moduleGraph.dependsOn(varModule, currModule)) {
220 :             // The variable reference violates a declared module dependency.
221 :             t.report(n, VIOLATED_MODULE_DEP_ERROR,
